create temp table _l29 (l08_title text, title text, description text, scheduled_date date, old_description text, old_questions jsonb) on commit drop;

insert into _l29 values
  ('Soul Reapers, Films and Fifteen Openings', 'Soul Reapers, Films and Fifteen Openings', 'A look at how Bleach was made, from Tite Kubo''s manga to the Thousand-Year Blood War.', '2026-11-21'::date, 'A look at how Bleach was made, from Tite Kubo''s manga to the Thousand-Year Blood War.', $o1q$[{"question":"Who handed her powers to Ichigo to turn him into a Substitute Soul Reaper?","options":["Orihime Inoue","Rukia Kuchiki","Isshin Kurosaki","Kisuke Urahara"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-ichigo-substitute-020"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"},{"question":"Which network aired the first Bleach anime between 2004 and 2012?","options":["Nippon Television","Fuji Television","TBS","TV Tokyo"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-anime-production-007"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"Who directed the original Bleach anime?","options":["Noriyuki Abe","Hayato Date","Tomohisa Taguchi","Shingo Natsume"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-anime-production-007"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"Which of the four Bleach films came out first, in December 2006?","options":["The DiamondDust Rebellion","Fade to Black","Memories of Nobody","Hell Verse"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-four-films-019"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"Which sequel series began on TV Tokyo on 11 October 2022?","options":["Boruto: Two Blue Vortex","Thousand-Year Blood War","Dragon Ball Daima","Naruto: Shippuden"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-blood-war-sequel-008"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(TV_series)"},{"question":"Which band sang *~Asterisk~, the first o