  ('Hidden Leaf Behind the Scenes', 'Hidden Leaf Behind the Scenes', 'Eight questions about the people, studio and songs behind the Naruto anime and manga.', '2026-11-22'::date, 'Eight questions about the people, studio and songs behind the Naruto anime and manga.', $o1q$[{"question":"How many episodes does the original Naruto anime run for before Shippuden begins?","options":["100","220","175","366"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Which studio animated Naruto?","options":["Madhouse","Bones","Studio Pierrot","Wit Studio"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"In which magazine was the Naruto manga serialized?","options":["Weekly Shonen Magazine","Weekly Shonen Sunday","Weekly Shonen Jump","Monthly Shonen Gangan"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"In which year did the Naruto manga begin in Weekly Shonen Jump?","options":["1999","2002","1996","2005"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-run-004"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Who designed the characters for the Naruto anime after the manga author asked for him?","options":["Yusuke Murata","Takeshi Obata","Akira Toriyama","Tetsuya Nishio"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-character-designer-024"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Akeboshi sang Wind at the start of the first Naruto series. Which much later ending did he also perform?","options":["ALIVE","Yellow moon","Ryusei","Harmonia"],"correct":1,"kind":"music","spoiler":{"arc":0,