  ('Cursed Energy Soundtrack', 'Cursed Energy Soundtrack', 'Eight questions on the acts and songs that open and close episodes of the Jujutsu Kaisen anime.', '2026-11-23'::date, 'Eight questions on the acts and songs that open and close episodes of the Jujutsu Kaisen anime.', $o1q$[{"question":"King Gnu performed Specialz. Which other Jujutsu Kaisen opening did the band perform?","options":["Vivid Vice","Where Our Blue Is","AIZO","Kaikai Kitan"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-opening-themes-004"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen_(TV_series)"},{"question":"Which act performed Vivid Vice, the second opening?","options":["King Gnu","Eve","Tatsuya Kitani","Who-ya Extended"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-opening-themes-004"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen_(TV_series)"},{"question":"Which singer performed the season 2 opening Where Our Blue Is?","options":["Soushi Sakiyama","Tatsuya Kitani","Eve","Jo0ji"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-opening-themes-004"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen_(TV_series)"},{"question":"Which act performed the ending Give It Back?","options":["ALI","Cö shu Nie","Hitsujibungaku","Jo0ji"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-ending-themes-005"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen_(TV_series)"},{"question":"Lost in Paradise was performed by ALI together with which featured artist?","options":["Milet","Jo0ji","Eve","Aklo"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-ending-themes-005"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen_(TV_series)"},{"question":"Which band performed the season 2 ending More than Words?","options":["ALI","Cö shu Nie","King Gnu","Hitsu