  ('Pen Names: Who Created These Manga?', 'Pen Names: Who Created These Manga?', 'Eight manga creators, each paired with the series they wrote and drew.', '2026-11-25'::date, 'Eight manga creators, each paired with the series they wrote and drew.', $o1q$[{"question":"Which of these manga did Tite Kubo write and draw?","options":["Bleach","Haikyu!!","Hunter x Hunter","Death Note"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"},{"question":"Which of these manga did Hajime Isayama write and draw?","options":["Attack on Titan","Vinland Saga","Fullmetal Alchemist","Blue Lock"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-manga-creator-011"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan"},{"question":"Which of these manga did Koyoharu Gotouge write and draw?","options":["Bleach","Demon Slayer","Dandadan","Kagurabachi"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-creator-003"],"source_url":"https://en.wikipedia.org/wiki/Demon_Slayer:_Kimetsu_no_Yaiba"},{"question":"Which of these manga is the work of Yoshihiro Togashi?","options":["Haikyu!!","Naruto","Hunter x Hunter","JoJo's Bizarre Adventure"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["hunter-x-hunter-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/List_of_Hunter_%C3%97_Hunter_characters"},{"question":"Which of these manga did Haruichi Furudate write and draw?","options":["Blue Lock","Hunter x Hunter","Haikyu!!","One Piece"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Haikyu!!"},{"question":"Which of these manga did Tatsuki Fujimoto write and draw?","options":["Dandadan","Kaiju No. 8","Jujutsu Kaisen","Chainsaw Man"],"correct":3,"kin