do $o1l$ declare n int; m int; begin
  if exists (
    select 1 from public.quiz_bank b join _l29 v on md5(lower(btrim(b.title))) in (md5(lower(btrim(v.title))), md5(lower(btrim(v.l08_title))))
    where b.site_id = 'anime' and (b.status = 'published' or b.published_quiz_id is not null) and b.scheduled_date = v.scheduled_date
  ) or exists (
    select 1 from public.quiz_bank b
    where b.site_id = 'anime' and md5(lower(btrim(b.title))) = md5('name that series: deep cuts') and b.scheduled_date = '2026-12-18' and (b.status = 'published' or b.published_quiz_id is not null)
  ) then
    raise exception 'L29 rollback refused: a row of the lot or the moved row is already published';
  end if;

  update public.quiz_bank b set title = v.l08_title, description = v.old_description, questions = v.old_questions, status = 'draft', scheduled_date = null,
    verified_at = null, verification_notes = null, updated_at = now()
  from _l29 v
  where b.site_id = 'anime' and md5(lower(btrim(b.title))) in (md5(lower(btrim(v.title))), md5(lower(btrim(v.l08_title))))
    and b.status = 'scheduled' and b.scheduled_date = v.scheduled_date and b.published_quiz_id is null;
  get diagnostics n = row_count;

  update public.quiz_bank b set scheduled_date = '2026-11-08', updated_at = now()
  where b.site_id = 'anime' and md5(lower(btrim(b.title))) = md5('name that series: deep cuts')
    and b.status = 'scheduled' and b.scheduled_date = '2026-12-18' and b.published_quiz_id is null;
  get diagnostics m = row_count;

  if n not in (0, 27) or m not in (0, 1) or (n = 27 and m <> 1) then
    raise exception 'L29 rollback self-check failed: % lot rows restored (expected 27 or 0), moved row restored % (expected 1 with the lot)', n, m;
  end if;
end $o1l$;
